// src/db/migrations-embedded.ts
var EMBEDDED_TENANT_MIGRATIONS = {
  "008_tenant_clients.sql": "-- Migration: 008_tenant_clients\r\n-- Tabela de clientes no schema do tenant\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n-- NOTA: Clients no schema do tenant N\xC3O t\xEAm company_id (isolados por schema)\r\n\r\nCREATE TABLE IF NOT EXISTS clients (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  name VARCHAR(255) NOT NULL,\r\n  cnpj VARCHAR(18) NOT NULL,\r\n  email VARCHAR(255),\r\n  status VARCHAR(50) NOT NULL DEFAULT 'active',\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  -- CNPJ \xFAnico por schema (n\xE3o precisa company_id, j\xE1 isolado por schema)\r\n  UNIQUE(cnpj)\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_clients_cnpj ON clients(cnpj);\r\nCREATE INDEX IF NOT EXISTS idx_clients_status ON clients(status);\r\nCREATE INDEX IF NOT EXISTS idx_clients_name ON clients(name);\r\n\r\n-- Trigger para updated_at\r\nCREATE TRIGGER update_clients_updated_at \r\n  BEFORE UPDATE ON clients \r\n  FOR EACH ROW \r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON TABLE clients IS 'Clientes da contabilidade (empresas atendidas) - isolados por schema';\r\nCOMMENT ON COLUMN clients.cnpj IS 'CNPJ \xFAnico por contabilidade (isolamento por schema)';\r\n",
  "009_client_tax_regime.sql": "-- Migration: 009_client_tax_regime\r\n-- Adiciona campos de regime tribut\xE1rio \xE0 tabela clients\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\n-- Adicionar campos ao clients\r\nALTER TABLE clients\r\n  ADD COLUMN IF NOT EXISTS tax_regime VARCHAR(50),\r\n  ADD COLUMN IF NOT EXISTS cnae VARCHAR(10),\r\n  ADD COLUMN IF NOT EXISTS state_registration VARCHAR(50),\r\n  ADD COLUMN IF NOT EXISTS municipal_registration VARCHAR(50),\r\n  ADD COLUMN IF NOT EXISTS notes TEXT;\r\n\r\n-- Criar \xEDndice para tax_regime (\xFAtil para filtros)\r\nCREATE INDEX IF NOT EXISTS idx_clients_tax_regime ON clients(tax_regime);\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON COLUMN clients.tax_regime IS 'Regime tribut\xE1rio: simples_nacional, lucro_presumido, lucro_real, outros';\r\nCOMMENT ON COLUMN clients.cnae IS 'C\xF3digo CNAE principal da empresa';\r\nCOMMENT ON COLUMN clients.state_registration IS 'Inscri\xE7\xE3o Estadual';\r\nCOMMENT ON COLUMN clients.municipal_registration IS 'Inscri\xE7\xE3o Municipal';\r\n",
  "010_fiscal_files.sql": "-- Migration: 010_fiscal_files\r\n-- Tabela de arquivos fiscais dos clientes\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS fiscal_files (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\r\n  file_type VARCHAR(50) NOT NULL,\r\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\r\n  file_name VARCHAR(255) NOT NULL,\r\n  file_path VARCHAR(500) NOT NULL, -- Path no Supabase Storage\r\n  file_size BIGINT NOT NULL,\r\n  mime_type VARCHAR(100),\r\n  status VARCHAR(50) NOT NULL DEFAULT 'uploaded',\r\n  processing_error TEXT,\r\n  metadata JSONB,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  -- Valida\xE7\xE3o de compet\xEAncia (formato YYYY-MM)\r\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$')\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_client_id ON fiscal_files(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_competence ON fiscal_files(competence);\r\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_status ON fiscal_files(status);\r\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_file_type ON fiscal_files(file_type);\r\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_client_competence ON fiscal_files(client_id, competence);\r\n\r\n-- Trigger para updated_at\r\nCREATE TRIGGER update_fiscal_files_updated_at \r\n  BEFORE UPDATE ON fiscal_files \r\n  FOR EACH ROW \r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON TABLE fiscal_files IS 'Arquivos fiscais enviados pelos clientes (SPED, ECD, PGDAS, etc)';\r\nCOMMENT ON COLUMN fiscal_files.file_type IS 'Tipo: sped, ecd, pgdas, xml, pdf, txt, outros';\r\nCOMMENT ON COLUMN fiscal_files.status IS 'Status: uploaded, processing, processed, error';\r\nCOMMENT ON COLUMN fiscal_files.competence IS 'Compet\xEAncia no formato YYYY-MM (ex: 2024-01)';\r\n",
  "011_extracted_data.sql": "-- Migration: 011_extracted_data\r\n-- Tabela de dados extra\xEDdos dos arquivos fiscais\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS extracted_fiscal_data (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  fiscal_file_id UUID NOT NULL REFERENCES fiscal_files(id) ON DELETE CASCADE,\r\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\r\n  data_type VARCHAR(50) NOT NULL,\r\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\r\n  data JSONB NOT NULL,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  -- Valida\xE7\xE3o de compet\xEAncia (formato YYYY-MM)\r\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$')\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_fiscal_file_id ON extracted_fiscal_data(fiscal_file_id);\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_client_id ON extracted_fiscal_data(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_data_type ON extracted_fiscal_data(data_type);\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_competence ON extracted_fiscal_data(competence);\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_client_competence ON extracted_fiscal_data(client_id, competence);\r\n\r\n-- \xCDndice GIN para busca em JSONB\r\nCREATE INDEX IF NOT EXISTS idx_extracted_data_data_gin ON extracted_fiscal_data USING GIN (data);\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON TABLE extracted_fiscal_data IS 'Dados estruturados extra\xEDdos dos arquivos fiscais';\r\nCOMMENT ON COLUMN extracted_fiscal_data.data_type IS 'Tipo: balance_sheet, dre, tax_liabilities, revenue, other';\r\nCOMMENT ON COLUMN extracted_fiscal_data.data IS 'Dados estruturados em JSONB';\r\nCOMMENT ON COLUMN extracted_fiscal_data.competence IS 'Compet\xEAncia no formato YYYY-MM (ex: 2024-01)';\r\n",
  "021_rating_validations.sql": "-- Migration: 021_rating_validations\r\n-- Tabela de valida\xE7\xF5es de Rating PGFN (CAPAG)\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS rating_validations (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\r\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\r\n  fiscal_file_id UUID REFERENCES fiscal_files(id) ON DELETE SET NULL, -- NULL para simula\xE7\xF5es\r\n  is_simulation BOOLEAN DEFAULT false,\r\n  \r\n  -- Dados de entrada (campos granulares)\r\n  input_data JSONB NOT NULL, -- Balan\xE7o e DRE usados (estrutura granular)\r\n  \r\n  -- Valores agregados calculados (para refer\xEAncia)\r\n  calculated_values JSONB, -- Valores intermedi\xE1rios calculados (ativo_circulante_total, etc.)\r\n  \r\n  -- Indicadores calculados\r\n  liquidez_corrente DECIMAL(15,4),\r\n  liquidez_geral DECIMAL(15,4),\r\n  solvencia DECIMAL(15,4),\r\n  \r\n  -- Ratings\r\n  rating_estimado VARCHAR(1) NOT NULL, -- A, B, C, D\r\n  rating_real VARCHAR(1), -- A, B, C, D (opcional)\r\n  \r\n  -- An\xE1lise\r\n  has_discrepancy BOOLEAN DEFAULT false,\r\n  discrepancy_details JSONB, -- Detalhes da discrep\xE2ncia\r\n  \r\n  -- Metadados\r\n  created_by UUID, -- Refer\xEAncia a users (pode ser NULL se n\xE3o houver user)\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  -- Valida\xE7\xE3o de compet\xEAncia (formato YYYY-MM)\r\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$'),\r\n  -- Valida\xE7\xE3o de rating\r\n  CONSTRAINT check_rating_estimado CHECK (rating_estimado IN ('A', 'B', 'C', 'D')),\r\n  CONSTRAINT check_rating_real CHECK (rating_real IS NULL OR rating_real IN ('A', 'B', 'C', 'D'))\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_client_id ON rating_validations(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_competence ON rating_validations(competence);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_fiscal_file_id ON rating_validations(fiscal_file_id);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_is_simulation ON rating_validations(is_simulation);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_rating_estimado ON rating_validations(rating_estimado);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_client_competence ON rating_validations(client_id, competence);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_created_at ON rating_validations(created_at DESC);\r\n\r\n-- \xCDndice GIN para busca em JSONB\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_input_data_gin ON rating_validations USING GIN (input_data);\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_calculated_values_gin ON rating_validations USING GIN (calculated_values);\r\n\r\n-- Trigger para updated_at\r\nCREATE TRIGGER update_rating_validations_updated_at \r\n  BEFORE UPDATE ON rating_validations \r\n  FOR EACH ROW \r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON TABLE rating_validations IS 'Valida\xE7\xF5es de Rating PGFN (CAPAG) - Simula\xE7\xF5es e valida\xE7\xF5es reais de ECD';\r\nCOMMENT ON COLUMN rating_validations.is_simulation IS 'true para simula\xE7\xF5es, false para valida\xE7\xF5es reais de ECD';\r\nCOMMENT ON COLUMN rating_validations.input_data IS 'Dados de entrada granulares (Balan\xE7o e DRE)';\r\nCOMMENT ON COLUMN rating_validations.calculated_values IS 'Valores agregados calculados automaticamente (ativo_circulante_total, etc.)';\r\nCOMMENT ON COLUMN rating_validations.rating_estimado IS 'Rating calculado pelos indicadores (A, B, C, D)';\r\nCOMMENT ON COLUMN rating_validations.rating_real IS 'Rating real informado pelo usu\xE1rio ou extra\xEDdo da ECD';\r\nCOMMENT ON COLUMN rating_validations.has_discrepancy IS 'true se rating_estimado != rating_real';\r\nCOMMENT ON COLUMN rating_validations.competence IS 'Compet\xEAncia no formato YYYY-MM (ex: 2024-01)';\r\n",
  "024_judicial_processes.sql": "-- Migration: 024_judicial_processes\r\n-- Tabela de processos judiciais dos clientes (para valida\xE7\xE3o de elegibilidade em editais de contencioso)\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS judicial_processes (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\r\n  process_number VARCHAR(50) NOT NULL, -- N\xFAmero do processo (ex: 1234567-89.2023.4.03.0001)\r\n  court VARCHAR(255), -- Tribunal/\xD3rg\xE3o (ex: TRF4, STJ, etc)\r\n  legal_thesis VARCHAR(100) NOT NULL, -- Tese jur\xEDdica: IPI_PRACA, PRL, IRPJ_CSLL_DESMUTUALIZACAO\r\n  case_value NUMERIC(15, 2), -- Valor da causa (em reais)\r\n  start_date DATE, -- Data de in\xEDcio do processo\r\n  status VARCHAR(50) NOT NULL DEFAULT 'active', -- active, suspended, closed\r\n  notes TEXT, -- Observa\xE7\xF5es adicionais\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  -- Valida\xE7\xE3o de tese jur\xEDdica\r\n  CONSTRAINT check_legal_thesis CHECK (legal_thesis IN ('IPI_PRACA', 'PRL', 'IRPJ_CSLL_DESMUTUALIZACAO'))\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_client_id ON judicial_processes(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_legal_thesis ON judicial_processes(legal_thesis);\r\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_status ON judicial_processes(status);\r\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_client_thesis ON judicial_processes(client_id, legal_thesis);\r\n\r\n-- Trigger para updated_at\r\nCREATE TRIGGER update_judicial_processes_updated_at \r\n  BEFORE UPDATE ON judicial_processes \r\n  FOR EACH ROW \r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON TABLE judicial_processes IS 'Processos judiciais dos clientes relacionados a teses tribut\xE1rias espec\xEDficas';\r\nCOMMENT ON COLUMN judicial_processes.legal_thesis IS 'Tese jur\xEDdica: IPI_PRACA (IPI - Conceito de Pra\xE7a), PRL (Pre\xE7o de Transfer\xEAncia), IRPJ_CSLL_DESMUTUALIZACAO (IRPJ/CSLL sobre desmutualiza\xE7\xE3o)';\r\nCOMMENT ON COLUMN judicial_processes.status IS 'Status: active (ativo), suspended (suspenso), closed (encerrado)';\r\nCOMMENT ON COLUMN judicial_processes.process_number IS 'N\xFAmero do processo judicial (formato livre)';\r\n",
  "025_in_2306_simulations.sql": "-- Migration: 025_in_2306_simulations\r\n-- Tabela de simula\xE7\xF5es da Nova IN 2.306/2026\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS in_2306_simulations (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL, -- Opcional para simula\xE7\xF5es sem v\xEDnculo\r\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\r\n  \r\n  -- Dados de entrada da simula\xE7\xE3o (estrutura flex\xEDvel conforme regras da IN 2.306/2026)\r\n  input_data JSONB NOT NULL,\r\n  \r\n  -- Resultado da simula\xE7\xE3o (valores calculados, parcelas, condi\xE7\xF5es, etc.)\r\n  result_data JSONB NOT NULL,\r\n  \r\n  -- Metadados\r\n  title VARCHAR(255), -- T\xEDtulo opcional da simula\xE7\xE3o\r\n  created_by UUID,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  \r\n  CONSTRAINT check_competence_format_in2306 CHECK (competence ~ '^\\d{4}-\\d{2}$')\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_client_id ON in_2306_simulations(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_competence ON in_2306_simulations(competence);\r\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_created_at ON in_2306_simulations(created_at DESC);\r\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_input_data_gin ON in_2306_simulations USING GIN (input_data);\r\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_result_data_gin ON in_2306_simulations USING GIN (result_data);\r\n\r\n-- Trigger para updated_at\r\nCREATE TRIGGER update_in_2306_simulations_updated_at\r\n  BEFORE UPDATE ON in_2306_simulations\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCOMMENT ON TABLE in_2306_simulations IS 'Simula\xE7\xF5es da Nova IN 2.306/2026 - Parcelamento e condi\xE7\xF5es fiscais';\r\nCOMMENT ON COLUMN in_2306_simulations.input_data IS 'Dados de entrada (valores, prazos, op\xE7\xF5es conforme IN 2.306/2026)';\r\nCOMMENT ON COLUMN in_2306_simulations.result_data IS 'Resultado da simula\xE7\xE3o (parcelas, totais, condi\xE7\xF5es aplic\xE1veis)';\r\n",
  "029_irpf_alta_renda.sql": "-- Migration: 029_irpf_alta_renda\r\n-- Tabela de simula\xE7\xF5es IRPF Alta Renda (Lei 15.270/2025)\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n-- company_id referencia public.companies (tenant/empresa a que a simula\xE7\xE3o pertence).\r\n\r\nCREATE TABLE IF NOT EXISTS irpf_alta_renda (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  company_id UUID REFERENCES public.companies(id) ON DELETE SET NULL,\r\n\r\n  ano INTEGER NOT NULL,\r\n  contribuinte_nome VARCHAR(255) NOT NULL,\r\n  contribuinte_cpf VARCHAR(14) NOT NULL,\r\n  rendimentos_tributaveis NUMERIC(18, 2) NOT NULL DEFAULT 0,\r\n  dados_dividendos JSONB NOT NULL DEFAULT '[]',\r\n  base_calculo_combinada NUMERIC(18, 2) NOT NULL,\r\n  resultado_simulacao JSONB NOT NULL,\r\n\r\n  title VARCHAR(255),\r\n  created_by UUID,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n\r\n  CONSTRAINT check_irpf_alta_renda_ano CHECK (ano >= 2020 AND ano <= 2035)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_company_id ON irpf_alta_renda(company_id);\r\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_ano ON irpf_alta_renda(ano);\r\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_created_at ON irpf_alta_renda(created_at DESC);\r\n\r\nCREATE TRIGGER update_irpf_alta_renda_updated_at\r\n  BEFORE UPDATE ON irpf_alta_renda\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCOMMENT ON TABLE irpf_alta_renda IS 'Simula\xE7\xF5es IRPF Alta Renda - Lei 15.270/2025';\r\nCOMMENT ON COLUMN irpf_alta_renda.dados_dividendos IS 'Array de fontes de rendimentos isentos (c\xF3digos 09 e 13)';\r\nCOMMENT ON COLUMN irpf_alta_renda.resultado_simulacao IS 'Resultado da simula\xE7\xE3o: faixa, al\xEDquota, imposto, risco de reten\xE7\xE3o';\r\n",
  "034_irpf_alta_renda_add_company_id.sql": "-- Migration: 034_irpf_alta_renda_add_company_id\r\n-- Adiciona coluna company_id \xE0 tabela irpf_alta_renda no schema do tenant.\r\n-- A migration 029 foi aplicada antes de essa coluna existir.\r\nALTER TABLE irpf_alta_renda\r\n  ADD COLUMN IF NOT EXISTS company_id UUID REFERENCES public.companies(id) ON DELETE SET NULL;\r\n\r\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_company_id ON irpf_alta_renda(company_id);\r\n",
  "036_properties.sql": "-- Migration: 036_properties\r\n-- Tabelas de im\xF3veis e transa\xE7\xF5es para m\xF3dulo de Gest\xE3o Imobili\xE1ria\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\n-- Tipo de loca\xE7\xE3o: fixa (mensal) ou flex\xEDvel (Airbnb/short-term)\r\n-- Tipo de transa\xE7\xE3o: receita, despesa_dedutivel, custo_operacional\r\n\r\nCREATE TABLE IF NOT EXISTS properties (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\r\n  tipo_locacao VARCHAR(20) NOT NULL CHECK (tipo_locacao IN ('fixa', 'flexivel')),\r\n  identificador VARCHAR(255) NOT NULL,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW()\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS property_transactions (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\r\n  mes_referencia VARCHAR(7) NOT NULL CHECK (mes_referencia ~ '^\\d{4}-\\d{2}$'),\r\n  tipo VARCHAR(30) NOT NULL CHECK (tipo IN ('receita', 'despesa_dedutivel', 'custo_operacional')),\r\n  categoria VARCHAR(50) NOT NULL,\r\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\r\n  observacao TEXT,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW()\r\n);\r\n\r\n-- \xCDndices\r\nCREATE INDEX IF NOT EXISTS idx_properties_client_id ON properties(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_properties_tipo_locacao ON properties(tipo_locacao);\r\nCREATE INDEX IF NOT EXISTS idx_property_transactions_property_id ON property_transactions(property_id);\r\nCREATE INDEX IF NOT EXISTS idx_property_transactions_mes_referencia ON property_transactions(mes_referencia);\r\nCREATE INDEX IF NOT EXISTS idx_property_transactions_tipo ON property_transactions(tipo);\r\nCREATE INDEX IF NOT EXISTS idx_property_transactions_property_mes ON property_transactions(property_id, mes_referencia);\r\n\r\n-- Triggers para updated_at\r\nCREATE TRIGGER update_properties_updated_at\r\n  BEFORE UPDATE ON properties\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCREATE TRIGGER update_property_transactions_updated_at\r\n  BEFORE UPDATE ON property_transactions\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCOMMENT ON TABLE properties IS 'Im\xF3veis para gest\xE3o patrimonial e planejamento tribut\xE1rio';\r\nCOMMENT ON TABLE property_transactions IS 'Lan\xE7amentos de receita e despesa por im\xF3vel (mensais)';\r\n",
  "038_property_monthly_totals.sql": "-- Migration: 038_property_monthly_totals\r\n-- Vers\xE3o reduzida: totais mensais por tipo (loca\xE7\xE3o longa e short)\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\n-- Adicionar modo_entrada ao property: detalhado (transa\xE7\xF5es) ou reduzido (totais mensais)\r\nALTER TABLE properties\r\n  ADD COLUMN IF NOT EXISTS modo_entrada VARCHAR(20) NOT NULL DEFAULT 'detalhado'\r\n  CHECK (modo_entrada IN ('detalhado', 'reduzido'));\r\n\r\n-- Tabela para modo reduzido: totais mensais (loca\xE7\xE3o longa + short)\r\nCREATE TABLE IF NOT EXISTS property_monthly_totals (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\r\n  mes_referencia VARCHAR(7) NOT NULL CHECK (mes_referencia ~ '^\\d{4}-\\d{2}$'),\r\n  receita_longa DECIMAL(15, 2) NOT NULL DEFAULT 0,\r\n  receita_short DECIMAL(15, 2) NOT NULL DEFAULT 0,\r\n  despesas_dedutiveis DECIMAL(15, 2) NOT NULL DEFAULT 0,\r\n  custos_operacionais DECIMAL(15, 2) NOT NULL DEFAULT 0,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  UNIQUE(property_id, mes_referencia)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_property_monthly_totals_property_id ON property_monthly_totals(property_id);\r\nCREATE INDEX IF NOT EXISTS idx_property_monthly_totals_mes ON property_monthly_totals(mes_referencia);\r\n\r\nCREATE TRIGGER update_property_monthly_totals_updated_at\r\n  BEFORE UPDATE ON property_monthly_totals\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCOMMENT ON TABLE property_monthly_totals IS 'Totais mensais (modo reduzido): loca\xE7\xE3o longa, short, despesas e custos';\r\nCOMMENT ON COLUMN properties.modo_entrada IS 'detalhado=transa\xE7\xF5es individuais; reduzido=totais mensais';\r\n",
  "040_irpf_alta_renda_payload_json.sql": "-- Migration: 040_irpf_alta_renda_payload_json\r\n-- Adiciona coluna payload_json para armazenar simula\xE7\xE3o completa (dados de entrada + resultado).\r\n-- Estrutura: tipo_importacao, arquivo_nome, ano, dados, resultado_simulacao, declaracao_completa, diagnostico.\r\n-- Mant\xE9m colunas existentes por compatibilidade (preenchidas a partir de payload_json ou vice-versa).\r\n\r\nALTER TABLE irpf_alta_renda\r\nADD COLUMN IF NOT EXISTS payload_json JSONB;\r\n\r\nCOMMENT ON COLUMN irpf_alta_renda.payload_json IS 'Payload completo: tipo_importacao, arquivo_nome, dados, resultado_simulacao, declaracao_completa, diagnostico';\r\n",
  "045_clients_person_type.sql": "-- Migration: 045_clients_person_type\r\n-- Suporte a pessoa f\xEDsica no cadastro de clientes\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\n-- Tornar cnpj nullable (PF n\xE3o tem CNPJ)\r\nALTER TABLE clients ALTER COLUMN cnpj DROP NOT NULL;\r\n\r\n-- Adicionar person_type e cpf\r\nALTER TABLE clients\r\n  ADD COLUMN IF NOT EXISTS person_type VARCHAR(2) DEFAULT 'pj',\r\n  ADD COLUMN IF NOT EXISTS cpf VARCHAR(14);\r\n\r\n-- Remover constraint UNIQUE(cnpj) se existir, pois agora cnpj pode ser NULL\r\n-- Em PostgreSQL, UNIQUE permite m\xFAltiplos NULLs, ent\xE3o a constraint pode permanecer\r\n-- Mas precisamos de unique em cpf quando preenchido\r\nCREATE UNIQUE INDEX IF NOT EXISTS idx_clients_cpf_unique ON clients(cpf) WHERE cpf IS NOT NULL;\r\n\r\nCOMMENT ON COLUMN clients.person_type IS 'pj = Pessoa Jur\xEDdica, pf = Pessoa F\xEDsica';\r\nCOMMENT ON COLUMN clients.cpf IS 'CPF do cliente quando person_type = pf';\r\n",
  "046_property_simulations.sql": "-- Migration: 046_property_simulations\r\n-- Tabela de simula\xE7\xF5es do Simulador Imobili\xE1rio (PF vs PJ vs Reforma)\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\nCREATE TABLE IF NOT EXISTS property_simulations (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,\r\n  ano INTEGER NOT NULL,\r\n  input_data JSONB NOT NULL,\r\n  result_data JSONB NOT NULL,\r\n  title VARCHAR(255),\r\n  created_by UUID,\r\n  created_at TIMESTAMP DEFAULT NOW(),\r\n  updated_at TIMESTAMP DEFAULT NOW(),\r\n  CONSTRAINT check_property_simulations_ano CHECK (ano >= 2020 AND ano <= 2035)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_property_simulations_client_id ON property_simulations(client_id);\r\nCREATE INDEX IF NOT EXISTS idx_property_simulations_ano ON property_simulations(ano);\r\nCREATE INDEX IF NOT EXISTS idx_property_simulations_created_at ON property_simulations(created_at DESC);\r\n\r\nCREATE TRIGGER update_property_simulations_updated_at\r\n  BEFORE UPDATE ON property_simulations\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION update_updated_at_column();\r\n\r\nCOMMENT ON TABLE property_simulations IS 'Simula\xE7\xF5es Simulador Imobili\xE1rio PF vs PJ vs Reforma 2027';\r\n",
  "048_rating_parcelamento_pgfn.sql": "-- Migration: 048_rating_parcelamento_pgfn\r\n-- Adiciona campo para armazenar dados do parcelamento PGFN junto com a simula\xE7\xE3o\r\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\r\n\r\n-- Adicionar coluna para armazenar dados do parcelamento PGFN\r\nALTER TABLE rating_validations \r\nADD COLUMN IF NOT EXISTS parcelamento_pgfn JSONB;\r\n\r\n-- Adicionar coluna para armazenar o comparativo calculado\r\nALTER TABLE rating_validations \r\nADD COLUMN IF NOT EXISTS comparativo_parcelamento JSONB;\r\n\r\n-- \xCDndice GIN para busca em JSONB do parcelamento\r\nCREATE INDEX IF NOT EXISTS idx_rating_validations_parcelamento_pgfn_gin \r\nON rating_validations USING GIN (parcelamento_pgfn) \r\nWHERE parcelamento_pgfn IS NOT NULL;\r\n\r\n-- Coment\xE1rios para documenta\xE7\xE3o\r\nCOMMENT ON COLUMN rating_validations.parcelamento_pgfn IS 'Dados do parcelamento PGFN extra\xEDdos do Recibo de Ades\xE3o (CNPJ, modalidade, d\xEDvidas, capacidade de pagamento, consolida\xE7\xE3o, pagamento)';\r\nCOMMENT ON COLUMN rating_validations.comparativo_parcelamento IS 'Comparativo entre rating calculado e parcelamento PGFN (cen\xE1rios, diferen\xE7a financeira, fundamenta\xE7\xE3o jur\xEDdica)';\r\n"
};

// src/db/schema-manager.ts
var MIGRATIONS_DIR = (0, import_path2.join)(__dirname, "migrations");
async function getMigrationSql(filename) {
  const embedded = EMBEDDED_TENANT_MIGRATIONS[filename];
  if (embedded && embedded.length > 0) return embedded;
  return (0, import_promises.readFile)((0, import_path2.join)(MIGRATIONS_DIR, filename), "utf-8");
}
async function createTenantSchema(companyId, client) {
  const schemaName = `tenant_${companyId.replace(/-/g, "_")}`;
  try {
    if (client) {
      await client.query(`CREATE SCHEMA IF NOT EXISTS "${schemaName}"`);
    } else {
      await query(`CREATE SCHEMA IF NOT EXISTS "${schemaName}"`);
    }
    console.log(`\u2705 Schema ${schemaName} criado com sucesso`);
  } catch (error) {
    console.error(`\u274C Erro ao criar schema ${schemaName}:`, error);
    throw error;
  }
}
async function applyTenantMigrations(companyId, client) {
  const schemaName = `tenant_${companyId.replace(/-/g, "_")}`;
  const useClient = client || await getClient();
  const shouldRelease = !client;
  try {
    await useClient.query(`
      CREATE TABLE IF NOT EXISTS "${schemaName}".schema_migrations (
        version INTEGER PRIMARY KEY,
        filename VARCHAR(255) NOT NULL,
        executed_at TIMESTAMP DEFAULT NOW()
      )
    `);
    const executedMigrations = await useClient.query(
      `SELECT version FROM "${schemaName}".schema_migrations ORDER BY version`
    );
    const executedVersions = new Set(executedMigrations.rows.map((m) => m.version));
    const tenantMigrations = [];
    for (const file of TENANT_MIGRATION_FILES) {
      const version4 = getTenantMigrationVersion(file);
      if (!executedVersions.has(version4)) {
        const sql = await getMigrationSql(file);
        tenantMigrations.push({ filename: file, version: version4, sql });
      }
    }
    if (tenantMigrations.length === 0) {
      console.log(`\u2705 Nenhuma migration de tenant pendente para ${schemaName}`);
      return;
    }
    console.log(`\u{1F4E6} ${tenantMigrations.length} migration(s) de tenant pendente(s) para ${schemaName}`);
    if (!client) {
      await useClient.query("BEGIN");
    }
    try {
      await useClient.query(`SET search_path TO "${schemaName}", public`);
      for (const migration of tenantMigrations) {
        console.log(`\u23F3 Executando: ${migration.filename} no schema ${schemaName}`);
        await useClient.query(migration.sql);
        await useClient.query(
          `INSERT INTO "${schemaName}".schema_migrations (version, filename) VALUES ($1, $2)`,
          [migration.version, migration.filename]
        );
        console.log(`\u2705 ${migration.filename} executada com sucesso no schema ${schemaName}`);
      }
      if (!client) {
        await useClient.query("COMMIT");
      }
      console.log(`\u2705 Todas as migrations de tenant foram aplicadas no schema ${schemaName}`);
    } catch (error) {
      if (!client) {
        await useClient.query("ROLLBACK");
      }
      throw error;
    } finally {
      if (shouldRelease) {
        useClient.release();
      }
    }
  } catch (error) {
    console.error(`\u274C Erro ao aplicar migrations de tenant no schema ${schemaName}:`, error);
    throw error;
  }
}

// src/modules/companies/company.service.ts
var CompanyService = class {
  constructor(companyRepo6) {
    this.companyRepo = companyRepo6;
  }
  /**
   * Criar empresa e seu schema de tenant
   */
  async create(data) {
    const client = await getClient();
    try {
      await client.query("BEGIN");
      if (data.domain) {
        const existingDomain = await client.query(
          "SELECT id FROM companies WHERE domain = $1 FOR UPDATE",
          [data.domain]
        );
        if (existingDomain.rows.length > 0) {
          await client.query("ROLLBACK");
          throw new AppError("Domain already exists", "DOMAIN_ALREADY_EXISTS", 409);
        }
      }
      if (data.cnpj) {
        const existingCnpj = await client.query(
          "SELECT id FROM companies WHERE cnpj = $1 FOR UPDATE",
          [data.cnpj]
        );
        if (existingCnpj.rows.length > 0) {
          await client.query("ROLLBACK");
          throw new AppError("CNPJ j\xE1 cadastrado", "CNPJ_ALREADY_EXISTS", 409);
        }
      }
      if (data.cpf) {
        const existingCpf = await client.query(
          "SELECT id FROM companies WHERE cpf = $1 FOR UPDATE",
          [data.cpf]
        );
        if (existingCpf.rows.length > 0) {
          await client.query("ROLLBACK");
          throw new AppError("CPF j\xE1 cadastrado", "CPF_ALREADY_EXISTS", 409);
        }
      }
      if (!data.cnpj) {
        const contactEmail = data.contact_email || data.email || "";
        const lockKey = `company_${data.name}_${contactEmail}`.substring(0, 100);
        await client.query(`SELECT pg_advisory_lock(hashtext($1))`, [lockKey]);
        try {
          const existingByName = await client.query(
            `SELECT id FROM companies WHERE name = $1 
             AND (contact_email = $2 OR email = $2 OR ($2 = '' AND contact_email IS NULL AND email IS NULL)) 
             AND (cnpj IS NULL OR cnpj = '') FOR UPDATE`,
            [data.name, contactEmail || null]
          );
          if (existingByName.rows.length > 0) {
            await client.query("ROLLBACK");
            throw new AppError("Empresa com mesmo nome e e-mail j\xE1 existe", "COMPANY_ALREADY_EXISTS", 409);
          }
        } finally {
          await client.query(`SELECT pg_advisory_unlock(hashtext($1))`, [lockKey]);
        }
      }
      const company = await this.companyRepo.create(data, client);
      const schemaName = `tenant_${company.id.replace(/-/g, "_")}`;
      const schemaExists = await client.query(
        `SELECT schema_name FROM information_schema.schemata WHERE schema_name = $1`,
        [schemaName]
      );
      if (schemaExists.rows.length === 0) {
        await createTenantSchema(company.id, client);
        await applyTenantMigrations(company.id, client);
      } else {
        console.warn(`\u26A0\uFE0F Schema ${schemaName} j\xE1 existe, pulando cria\xE7\xE3o`);
      }
      await client.query("COMMIT");
      console.log(`\u2705 Company ${company.id} criada com schema tenant_${company.id}`);
      return company;
    } catch (error) {
      await client.query("ROLLBACK");
      console.error("\u274C Erro ao criar company:", error);
      if (error.code === "23505") {
        if (error.constraint?.includes("cnpj")) {
          throw new AppError("CNPJ j\xE1 cadastrado", "CNPJ_ALREADY_EXISTS", 409);
        }
        if (error.constraint?.includes("cpf")) {
          throw new AppError("CPF j\xE1 cadastrado", "CPF_ALREADY_EXISTS", 409);
        }
        if (error.constraint?.includes("domain")) {
          throw new AppError("Dom\xEDnio j\xE1 cadastrado", "DOMAIN_ALREADY_EXISTS", 409);
        }
      }
      throw error;
    } finally {
      client.release();
    }
  }
  /**
   * Atualizar empresa
   */
  async update(id, data) {
    const company = await this.companyRepo.findById(id);
    if (!company) {
      throw new AppError("Company not found", "COMPANY_NOT_FOUND", 404);
    }
    if (data.domain && data.domain !== company.domain) {
      const existing = await this.companyRepo.findByDomain(data.domain);
      if (existing) {
        throw new AppError("Domain already exists", "DOMAIN_ALREADY_EXISTS", 409);
      }
    }
    return this.companyRepo.update(id, data);
  }
  /**
   * Buscar empresa por ID
   */
  async getById(id) {
    const company = await this.companyRepo.findById(id);
    if (!company) {
      throw new AppError("Company not found", "COMPANY_NOT_FOUND", 404);
    }
    return company;
  }
  /**
   * Buscar empresa por domain
   */
  async getByDomain(domain) {
    const company = await this.companyRepo.findByDomain(domain);
    if (!company) {
      throw new AppError("Company not found", "COMPANY_NOT_FOUND", 404);
    }
    return company;
  }
};

